Meridian Credits release 2.0 agreement (current when release is omitted; also applies to explicit "release":"2.0" requests). Source: Finance-approved specification in issue trial-b39, 2026-09-07. Explicit "release":"1.0" requests remain governed by the historical meridian-credits-release-1-0 agreement. A charge line has exactly nonempty string line_id/account_id/subscription_id, valid 2020-01-01 through 2099-12-31 Gregorian service_on, and nonnegative integer charge_cents; line_id is request-unique. Group all lines with the same account_id, including lines from distinct subscriptions. Calculate each uncapped line credit independently as floor(charge_cents * 15 / 100). Allocate a shared 3000-cent account cap by descending charge_cents, then increasing Unicode-code-point line_id on ties. Each assigned credit is min(uncapped credit, remaining group cap). No service date excludes a line. Total credit is assigned-credit sum; total due is charges minus total credit. A one-line quote treats its supplied line as its complete statement. Quote responses have exactly release "2.0", copied line_id, credit_cents, and amount_due_cents; total responses have exactly release "2.0", credit_cents, and amount_due_cents. Ping and unknown-command responses are unchanged.
#!/usr/bin/env python3
"""Meridian Credits local JSON CLI."""
import json
import sys


RELEASE_1_0 = "1.0"
RELEASE_2_0 = "2.0"
CURRENT_RELEASE = RELEASE_2_0


def quote_line(line, release):
    """Quote one charge line as a complete, one-line statement."""
    credit_cents = allocated_credits([line], release)[line["line_id"]]
    return {
        "release": release,
        "line_id": line["line_id"],
        "credit_cents": credit_cents,
        "amount_due_cents": line["charge_cents"] - credit_cents,
    }


def allocated_credits(lines, release):
    """Allocate shared credit caps according to the selected agreement."""
    lines_by_cap_group = {}
    for line in lines:
        if release == RELEASE_1_0:
            cap_group = (line["account_id"], line["subscription_id"])
        else:
            cap_group = line["account_id"]
        lines_by_cap_group.setdefault(cap_group, []).append(line)

    credits = {}
    for group_lines in lines_by_cap_group.values():
        if release == RELEASE_1_0:
            cap_cents = 2400
            ordered_lines = sorted(group_lines, key=lambda item: (item["service_on"], item["line_id"]))
            uncapped_credit = lambda line: line["charge_cents"] * 10 // 100
        else:
            cap_cents = 3000
            ordered_lines = sorted(group_lines, key=lambda item: (-item["charge_cents"], item["line_id"]))
            uncapped_credit = lambda line: line["charge_cents"] * 15 // 100

        remaining_credit = cap_cents
        for line in ordered_lines:
            credit_cents = min(uncapped_credit(line), remaining_credit)
            credits[line["line_id"]] = credit_cents
            remaining_credit -= credit_cents
    return credits


def total_statement(lines, release):
    """Quote the supplied complete monthly statement under the selected agreement."""
    credits = allocated_credits(lines, release)
    total_credit_cents = sum(credits.values())
    total_charge_cents = sum(line["charge_cents"] for line in lines)
    return {
        "release": release,
        "credit_cents": total_credit_cents,
        "amount_due_cents": total_charge_cents - total_credit_cents,
    }


def statement(lines, release):
    """Show allocated credit and amount due for every supplied charge line."""
    credits = allocated_credits(lines, release)
    total_credit_cents = sum(credits.values())
    total_charge_cents = sum(line["charge_cents"] for line in lines)
    return {
        "release": release,
        "lines": [
            {
                "line_id": line["line_id"],
                "credit_cents": credits[line["line_id"]],
                "amount_due_cents": line["charge_cents"] - credits[line["line_id"]],
            }
            for line in lines
        ],
        "credit_cents": total_credit_cents,
        "amount_due_cents": total_charge_cents - total_credit_cents,
    }


def handle(request):
    if request.get("command") == "ping":
        return {"status": "ok", "product": "Meridian Credits"}
    release = request.get("release", CURRENT_RELEASE)
    if request.get("command") == "quote" and release in (RELEASE_1_0, RELEASE_2_0):
        return quote_line(request["line"], release)
    if request.get("command") == "total" and release in (RELEASE_1_0, RELEASE_2_0):
        return total_statement(request["lines"], release)
    if request.get("command") == "statement" and release in (RELEASE_1_0, RELEASE_2_0):
        return statement(request["lines"], release)
    return {"error": "unknown_command"}


if __name__ == "__main__":
    json.dump(handle(json.load(sys.stdin)), sys.stdout)
    sys.stdout.write("\n")
"""Run one supplied public case file against the local application/artifacts."""
import argparse
import json
from pathlib import Path
import subprocess
import sys


def equal(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(equal(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(equal(a, b) for a, b in zip(left, right))
    return left == right


parser = argparse.ArgumentParser()
parser.add_argument("--cases", required=True)
args = parser.parse_args()
failed = 0
for case in json.loads(Path(args.cases).read_text()):
    try:
        if "artifact_json_path" in case:
            got = json.loads(Path(case["artifact_json_path"]).read_text())
        else:
            proc = subprocess.run([sys.executable, "main.py"], input=json.dumps(case["request"]),
                                  capture_output=True, text=True, check=True, timeout=5)
            got = json.loads(proc.stdout)
        ok = equal(got, case["expected"])
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        ok = False
        got = str(exc)
    print(("PASS " if ok else "FAIL ") + case["name"])
    if not ok:
        print(" expected:", case["expected"])
        print(" received:", got)
        failed += 1
raise SystemExit(bool(failed))
